1	'use strict';
2	
3	const { createHash } = require('node:crypto');
4	const { ValidationError } = require('./errors');
5	
6	/**
7	 * Deterministic integer simulation core.
8	 *
9	 * The engine uses integer arithmetic only: no floating point, no Date, no
10	 * Math.random, no locale-sensitive comparison. Given the same match
11	 * configuration and the same *set* of input records the sequence of states -
12	 * and therefore every state hash - is reproducible, whatever order those
13	 * records reached the service in.
14	 */
15	
16	const SCHEMA_VERSION = 1;
17	const STATE_DOMAIN = 'lockstepnet.state.v1\n';
18	const POSITION_MIN = 0;
19	const POSITION_MAX = 1000;
20	const HEALTH_MAX = 100;
21	const ATTACK_BASE = 10;
22	const MAX_TICKS_LIMIT = 100000;
23	const MAX_STEP = 1024;
24	const MAX_UNITS = 32;
25	const TEAMS = ['blue', 'red'];
26	const COMMAND_ORDER = ['move', 'attack'];
27	// Canonical order inside one tick: move commands first, then attacks.
28	const COMMAND_RANK = { move: 0, attack: 1 };
29	
30	function identifier(value, field, maxLength = 64) {
31	  if (typeof value !== 'string' || value.length === 0 || value.length > maxLength) {
32	    throw new ValidationError(`${field} must be a non-empty string of at most ${maxLength} characters`);
33	  }
34	  if (!/^[A-Za-z0-9][A-Za-z0-9_.:-]*$/.test(value)) {
35	    throw new ValidationError(`${field} must match ^[A-Za-z0-9][A-Za-z0-9_.:-]*$`);
36	  }
37	  return value;
38	}
39	
40	function integer(value, field, min, max) {
41	  if (!Number.isInteger(value) || value < min || value > max) {
42	    throw new ValidationError(`${field} must be an integer between ${min} and ${max}`);
43	  }
44	  return value;
45	}
46	
47	function exactKeys(raw, allowed, field) {
48	  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) {
49	    throw new ValidationError(`${field} must be an object`);
50	  }
51	  for (const key of Object.keys(raw)) {
52	    if (!allowed.includes(key)) {
53	      throw new ValidationError(`${field} has unknown field ${key}`);
54	    }
55	  }
56	}
57	
58	function requireKeys(raw, required, field) {
59	  for (const key of required) {
60	    if (!Object.prototype.hasOwnProperty.call(raw, key)) {
61	      throw new ValidationError(`${field} must contain ${required.join(', ')}`);
62	    }
63	  }
64	}
65	
66	function byId(left, right) {
67	  return left.id < right.id ? -1 : left.id > right.id ? 1 : 0;
68	}
69	
70	/** Parse and validate the immutable match configuration accepted by POST /matches. */
71	function parseConfig(raw) {
72	  exactKeys(raw, ['id', 'seed', 'max_ticks', 'units'], 'match');
73	  requireKeys(raw, ['id', 'units'], 'match');
74	  const id = identifier(raw.id, 'match id');
75	  const seed = raw.seed === undefined ? 0 : integer(raw.seed, 'seed', 0, 2147483647);
76	  const maxTicks = raw.max_ticks === undefined ? 1000 : integer(raw.max_ticks, 'max_ticks', 1, MAX_TICKS_LIMIT);
77	  if (!Array.isArray(raw.units) || raw.units.length === 0) {
78	    throw new ValidationError('units must be a non-empty array');
79	  }
80	  if (raw.units.length > MAX_UNITS) {
81	    throw new ValidationError(`units must contain at most ${MAX_UNITS} entries`);
82	  }
83	  const units = [];
84	  const seen = new Set();
85	  for (const entry of raw.units) {
86	    exactKeys(entry, ['id', 'team', 'position', 'velocity'], 'each unit');
87	    requireKeys(entry, ['id', 'team'], 'each unit');
88	    const unitId = identifier(entry.id, 'unit id');
89	    if (seen.has(unitId)) {
90	      throw new ValidationError(`unit ids must be unique: ${unitId}`);
91	    }
92	    seen.add(unitId);
93	    if (!TEAMS.includes(entry.team)) {
94	      throw new ValidationError(`unit ${unitId} team must be one of ${TEAMS.join(', ')}`);
95	    }
96	    const position = entry.position === undefined
97	      ? (entry.team === 'red' ? POSITION_MIN : POSITION_MAX)
98	      : integer(entry.position, `unit ${unitId} position`, POSITION_MIN, POSITION_MAX);
99	    const velocity = entry.velocity === undefined
100	      ? (entry.team === 'red' ? 5 : -5)
101	      : integer(entry.velocity, `unit ${unitId} velocity`, -POSITION_MAX, POSITION_MAX);
102	    units.push({ id: unitId, position, team: entry.team, velocity });
103	  }
104	  units.sort(byId);
105	  if (!units.some((unit) => unit.team === 'red') || !units.some((unit) => unit.team === 'blue')) {
106	    throw new ValidationError('units must contain at least one unit on each team');
107	  }
108	  return { id, maxTicks, seed, units };
109	}
110	
111	/** Fresh, hashable match state for a validated configuration. */
112	function initialState(config) {
113	  const units = {};
114	  for (const unit of config.units) {
115	    units[unit.id] = {
116	      attacking: false, health: HEALTH_MAX, id: unit.id,
117	      position: unit.position, team: unit.team, velocity: unit.velocity,
118	    };
119	  }
120	  return { hash: null, maxTicks: config.maxTicks, status: 'running', teamDamage: { blue: 0, red: 0 }, tick: 0, units };
121	}
122	
123	function cloneState(state) {
124	  const units = {};
125	  for (const id of Object.keys(state.units).sort()) {
126	    units[id] = { ...state.units[id] };
127	  }
128	  return {
129	    hash: state.hash, maxTicks: state.maxTicks, status: state.status,
130	    teamDamage: { blue: state.teamDamage.blue, red: state.teamDamage.red },
131	    tick: state.tick, units,
132	  };
133	}
134	
135	function liveUnits(state, team) {
136	  return Object.values(state.units)
137	    .filter((unit) => unit.health > 0 && (team === undefined || unit.team === team))
138	    .sort(byId);
139	}
140	
141	function opponentOf(team) {
