487	  unitsAt(matchId, unitIds, tick, current) {
488	    let source;
489	    if (tick >= current.tick) {
490	      source = current.units;
491	    } else if (tick <= 0) {
492	      source = sim.initialState(this.config(matchId)).units;
493	    } else {
494	      const frame = this.store.readFrames(matchId).find((candidate) => candidate.tick === tick);
495	      if (!frame) {
496	        throw new IntegrityError(`match ${matchId} has no recorded frame ${tick}`);
497	      }
498	      source = {};
499	      for (const unit of frame.state.units) {
500	        source[unit.id] = unit;
501	      }
502	    }
503	    return unitIds.map((id) => {
504	      const unit = source[id];
505	      if (!unit) {
506	        throw new IntegrityError(`frame ${tick} of match ${matchId} is missing unit ${id}`);
507	      }
508	      return {
509	        alive: unit.health > 0, attacking: unit.attacking, health: unit.health,
510	        id: unit.id, position: unit.position, team: unit.team, velocity: unit.velocity,
511	      };
512	    });
513	  }
514	
515	  /** Load a match's spectator or fail with 404; never returns null. */
516	  requireSpectator(matchId, spectatorId) {
517	    this.match(matchId);
518	    const spectator = this.store.readSpectator(matchId, spectatorId);
519	    if (!spectator) {
520	      throw new NotFoundError(`spectator ${spectatorId} of match ${matchId} was not found`);
521	    }
522	    return spectator;
523	  }
524	
525	  /**
526	   * The frame a spectator may currently see: the frontier delayed by
527	   * `delay_ticks` while a match runs, or the final tick once it has ended. A
528	   * finished match is frozen, so its spectators catch up to the very end instead
529	   * of trailing forever.
530	   */
531	  visibleTick(spectator, state) {
532	    if (state.status !== 'running') {
533	      return state.tick;
534	    }
535	    return Math.max(0, state.tick - spectator.delayTicks);
536	  }
537	
538	  /**
539	   * Register a spectator: a passive reader that trails the live frontier by
540	   * `delay_ticks`. Spectators are bookkeeping only: creating one never advances
541	   * the match and never enters a `state_hash` or `replay_hash`.
542	   */
543	  createSpectator(matchId, raw, key) {
544	    const record = this.match(matchId);
545	    sim.exactKeys(raw, ['id', 'delay_ticks'], 'body');
546	    if (raw.id === undefined || raw.delay_ticks === undefined) {
547	      throw new ValidationError('body must contain id and delay_ticks');
548	    }
549	    const spectatorId = sim.identifier(raw.id, 'spectator id');
550	    const delayTicks = sim.integer(raw.delay_ticks, 'delay_ticks', 0, MAX_SPECTATOR_DELAY);
551	    return this.idempotent(key, `create-spectator:${matchId}`, raw, () => {
552	      if (this.store.readSpectator(matchId, spectatorId)) {
553	        throw new ConflictError(`spectator ${spectatorId} already exists for match ${matchId}`);
554	      }
555	      const spectator = { delayTicks, highWater: 0, id: spectatorId, maxDelivered: 0, reset: false };
556	      this.store.insertSpectator(matchId, spectator);
557	      const state = this.store.readState(matchId);
558	      return {
559	        delay_ticks: delayTicks,
560	        match_id: matchId,
561	        spectator_id: spectatorId,
562	        visible_tick: this.visibleTick(spectator, state),
563	      };
564	    });
565	  }
566	
567	  /**
568	   * Poll a spectator's delayed stream.
569	   *
570	   * In normal `stream` mode the response carries the contiguous recorded frames
571	   * strictly after `after_tick` up to the spectator's `visible_tick`, at most
572	   * `limit` frames, followed by the state at the end of the returned window.
573	   * `complete` is true only when the window reached `visible_tick`.
574	   *
575	   * When a rollback (a late input or the explicit endpoint) rewrites a frame the
576	   * spectator had already received, the spectator is marked for reset: the next
577	   * poll ignores `after_tick`, replays from tick 0 in pages of `limit`, and
578	   * reports `mode: "reset"` until the reset stream catches back up.
579	   */
580	  pollSpectator(matchId, spectatorId, raw, key) {
581	    const spectator = this.requireSpectator(matchId, spectatorId);
582	    sim.exactKeys(raw, ['after_tick', 'limit'], 'body');
583	    const afterTick = raw.after_tick === undefined ? 0 : raw.after_tick;
584	    if (!Number.isInteger(afterTick) || afterTick < 0) {
585	      throw new ValidationError('after_tick must be a non-negative integer');
586	    }
587	    const limit = raw.limit === undefined ? sim.MAX_STEP : raw.limit;
588	    if (!Number.isInteger(limit) || limit < 1 || limit > sim.MAX_STEP) {
589	      throw new ValidationError(`limit must be an integer between 1 and ${sim.MAX_STEP}`);
590	    }
591	    return this.idempotent(key, `poll-spectator:${matchId}:${spectatorId}`, raw, () => {
592	      const state = this.store.readState(matchId);
593	      const visible = this.visibleTick(spectator, state);
594	      if (!spectator.reset && afterTick > visible) {
595	        throw new ConflictError(`after_tick ${afterTick} is past the visible tick ${visible}`);
596	      }
597	
598	      let mode = 'stream';
599	      let startTick = afterTick;
600	      if (spectator.reset) {
601	        // A reset replays the whole history from tick 0 in limit-sized pages;
602	        // after_tick from the client is discarded. The spectator's high-water
603	        // mark, rewound to 0 when the reset was flagged, is the paging cursor.
604	        mode = 'reset';
605	        startTick = spectator.highWater;
606	      }
607	
608	      const end = Math.min(startTick + limit, visible);
609	      const frames = this.spectatorFrames(matchId, startTick, end);
610	      const reached = startTick + frames.length;
611	
612	      let complete;
613	      let nextReset = spectator.reset;
614	      if (spectator.reset) {
615	        complete = reached >= visible;
616	        nextReset = !complete;
617	      } else {
618	        complete = reached >= visible;
619	      }
620	
621	      const updated = {
622	        ...spectator,
623	        highWater: reached,
624	        maxDelivered: Math.max(spectator.maxDelivered, reached),
625	        reset: nextReset,
626	      };
627	      this.store.writeSpectator(matchId, updated);
628	
629	      return {
630	        complete,
631	        frames,
632	        match_id: matchId,
633	        mode,
634	        next_tick: reached,
635	        spectator_id: spectatorId,
636	        state_hash: this.frameHashAt(matchId, reached),
637	        team_damage: this.teamDamageAt(matchId, reached, state),
638	        units: this.allUnitsAt(matchId, reached, state),
639	      };
640	    });
641	  }
642	
643	  /**
644	   * Contiguous recorded frames with ticks in `(startTick, endTick]`, each
645	   * re-derived from the snapshot before the window and checked against its
646	   * recorded hash. A gap or a recomputation mismatch is an `integrity_failure`
647	   * rather than an inconsistent stream.
648	   */
649	  spectatorFrames(matchId, startTick, endTick) {
650	    if (endTick <= startTick) {
651	      return [];
652	    }
653	    const byTick = new Map();
654	    for (const frame of this.store.readFramesFrom(matchId, startTick + 1)) {
655	      byTick.set(frame.tick, frame);
656	    }
657	    const frames = [];
658	    for (let tick = startTick + 1; tick <= endTick; tick += 1) {
659	      const frame = byTick.get(tick);
660	      if (!frame) {
661	        throw new IntegrityError(`match ${matchId} is missing recorded frame ${tick}`);
662	      }
663	      frames.push({
664	        casualties: frame.delta.casualties, settled: frame.settled,
665	        state_hash: frame.state_hash, tick: frame.tick,
666	      });
667	    }
668	    this.verifyWindow(matchId, startTick, frames);
669	    return frames;
670	  }
671	
672	  /** Every unit snapshot as it is at frame `tick`, sorted by unit id. */
673	  allUnitsAt(matchId, tick, current) {
674	    return this.unitsAt(
675	      matchId,
676	      this.config(matchId).units.map((unit) => unit.id),
677	      tick,
678	      current,
679	    ).sort((left, right) => (left.id < right.id ? -1 : left.id > right.id ? 1 : 0));
680	  }
681	
682	  /**
683	   * Advance a match by `count` ticks (default 1).
684	   *
685	   * The frontier never passes `max_ticks`, and the simulation stops early when a
686	   * team is eliminated. Advancing a match that is not `running` is a 409.
687	   */
688	  advance(matchId, raw, key) {
689	    const config = this.config(matchId);
690	    const body = raw === undefined || raw === null ? { count: 1 } : raw;
691	    sim.exactKeys(body, ['count'], 'body');
692	    const count = body.count === undefined ? 1 : body.count;
693	    if (!Number.isInteger(count) || count < 1 || count > sim.MAX_STEP) {
694	      throw new ValidationError(`count must be an integer between 1 and ${sim.MAX_STEP}`);
695	    }
696	    return this.idempotent(key, `advance:${matchId}`, { count }, () => {
697	      const before = this.store.readState(matchId);
698	      if (before.status !== 'running') {
699	        throw new ConflictError(`match ${matchId} is ${before.status} and cannot advance`);
700	      }
701	      const target = Math.min(before.tick + count, config.maxTicks);
702	      const { frames } = this.resimulate(matchId, before.tick, target, false);
703	      const updated = this.store.readState(matchId);
704	      return {
705	        ...this.describe(config, updated),
706	        advanced: frames.length,
707	        frames: frames.map((frame) => ({
708	          casualties: frame.delta.casualties, settled: frame.settled,
709	          state_hash: frame.state_hash, tick: frame.tick,
710	        })),
711	        state_hash: updated.hash,
712	      };
713	    });
714	  }
715	
716	  /**
717	   * Explicit rollback: rewind the match to `tick` by discarding every frame after
718	   * it. Input records are never discarded, so the next `POST /tick` replays them
719	   * and reproduces exactly the hashes recorded before the rollback.
720	   */
721	  rollback(matchId, tick) {
722	    const record = this.match(matchId);
723	    if (!Number.isInteger(tick) || tick < 0 || tick > record.config.maxTicks) {
724	      throw new ValidationError(`tick must be an integer between 0 and ${record.config.maxTicks}`);
725	    }
726	    const before = this.store.readState(matchId);
727	    if (tick > before.tick) {
728	      throw new ConflictError(`tick ${tick} is past the current tick ${before.tick}`);
729	    }
730	    this.resimulate(matchId, tick, tick, false);
731	    const after = this.store.readState(matchId);
732	    return {
733	      frames_recomputed: before.tick - tick,
734	      from_tick: before.tick, hash_after: after.hash, hash_before: before.hash,
735	      match_id: matchId, tick: after.tick, to_tick: tick,
736	    };
737	  }
738	
739	  /** The whole match as a portable replay document. */
740	  replayFile(matchId) {
741	    const record = this.match(matchId);
742	    const frames = this.store.readFrames(matchId).map((frame) => ({
743	      delta: frame.delta, settled: frame.settled, settled_inputs: frame.inputs,
744	      state_hash: frame.state_hash, tick: frame.tick,
745	    }));
746	    return replay.buildFile(record.config, frames, this.store.readInputs(matchId));
747	  }
748	
749	  /**
750	   * `POST /matches/{id}/verify` accepts either `{"match_id": "..."}` to
751	   * re-simulate a stored match, or `{"replay": {...}}` for an uploaded replay.
752	   */
753	  verify(raw) {
754	    sim.exactKeys(raw, ['match_id', 'replay'], 'body');
755	    if (raw.replay !== undefined && raw.match_id !== undefined) {
756	      throw new ValidationError('provide either match_id or replay, not both');
757	    }
758	    if (raw.replay !== undefined) {
759	      return this.verifyDocument(raw.replay);
760	    }
761	    if (typeof raw.match_id !== 'string' || raw.match_id.length === 0) {
762	      throw new ValidationError('match_id must be a non-empty string');
763	    }
764	    return this.verifyDocument(this.replayFile(raw.match_id));
765	  }
766	
767	  verifyDocument(document) {
768	    const result = replay.verifyDocument(document);
769	    const stored = this.store.readMatch(result.config.id);
770	    const mismatches = result.mismatches.slice();
771	    let recordedHash = null;
772	    if (stored && stored.tick === result.state.tick) {
773	      recordedHash = stored.stateHash;
774	      if (recordedHash !== result.state_hash) {
775	        mismatches.push({
776	          kind: 'state_hash',
777	          message: 'replayed final state does not match the stored match state',
778	          recorded: recordedHash, recomputed: result.state_hash, tick: result.state.tick,
779	        });
780	      }
781	    }
782	    return {
783	      consistent: mismatches.length === 0,
784	      final_state_hash: result.state_hash,
785	      match_id: result.config.id,
786	      mismatches,
787	      recorded_state_hash: recordedHash,
788	      replay_hash: result.replay_hash,
789	      ticks_replayed: result.frames.length,
790	    };
791	  }
792	
793	  /**
794	   * Rebuild the frame log from `resumeTick` up to `targetTick`.
795	   *
796	   * Frames after `resumeTick` are discarded and re-derived from the snapshot at
797	   * `resumeTick` plus the stored input records. Every rebuilt frame that already
798	   * existed must keep its hash; a divergence means the log or the engine changed
799	   * and is reported as `integrity_failure` instead of silently changing results.
800	   *
801	   * `extend` lets the match simulate past `targetTick` until a team is eliminated
802	   * or `max_ticks` is reached. `POST /tick` does not extend: stopping exactly at
803	   * the requested tick is what makes rollback-then-advance reproduce hashes.
804	   */
805	  resimulate(matchId, resumeTick, targetTick, extend = false) {
806	    const config = this.config(matchId);
807	    if (targetTick < resumeTick) {
808	      throw new IntegrityError(`cannot resimulate ${matchId} backwards from ${resumeTick} to ${targetTick}`);
809	    }
810	    const expected = new Map();
811	    for (const frame of this.store.readFramesFrom(matchId, resumeTick + 1)) {
812	      expected.set(frame.tick, frame.state_hash);
813	    }
814	    // `resumeTick` is a *frame* number: resuming continues from the state that
815	    // frame recorded, and must read it before the log is trimmed.
816	    const state = this.snapshotAt(matchId, resumeTick);
817	    const resumeStatus = state.status;
818	    this.store.deleteFramesFrom(matchId, resumeTick + 1);
819	    // A spectator whose delayed stream already held a frame this rebuild
820	    // discards must restart from tick 0. A plain forward advance never reaches
821	    // this branch with such a spectator: its visible window lags the frontier,
822	    // so its high-water mark cannot pass the old frontier.
823	    for (const spectator of this.store.readSpectatorsPast(matchId, resumeTick)) {
824	      // Rewind the reset paging cursor to 0 so the replay restarts at tick 0.
825	      // The monotonic max-delivered mark is kept: it is what triggered this and
826	      // continues to describe how far this spectator has ever seen.
827	      spectator.highWater = 0;
828	      spectator.reset = true;
829	      this.store.writeSpectator(matchId, spectator);
830	    }
831	    const buckets = new Map();
832	    for (const input of this.store.readInputs(matchId)) {
833	      const bucket = buckets.get(input.tick);
834	      if (bucket) {
835	        bucket.push(input.body);
836	      } else {
837	        buckets.set(input.tick, [input.body]);
838	      }
839	    }
840	    for (const bucket of buckets.values()) {
841	      bucket.sort(sim.compareInputs);
842	    }
843	
844	    state.status = 'running';
845	    const boundary = extend ? config.maxTicks : targetTick;
846	    const rebuilt = [];
847	    let endedNaturally = false;
848	    // Iteration `produced` applies the inputs of tick `produced - 1` and records
849	    // frame `produced`.
850	    for (let produced = resumeTick + 1; produced <= boundary; produced += 1) {
851	      const aliveAtStart = Object.values(state.units).filter((unit) => unit.health > 0).length;
852	      const settled = buckets.get(state.tick) || [];
853	      const delta = sim.applyTick(state, settled);
854	      state.hash = sim.stateHash(state);
855	      const recorded = expected.get(state.tick);
856	      if (recorded !== undefined && recorded !== state.hash) {
857	        throw new IntegrityError(
858	          `frame ${state.tick} of match ${matchId} recomputed to ${state.hash} but was recorded as ${recorded}`,
859	        );
860	      }
861	      const frame = {
862	        alive: aliveAtStart,
863	        delta,
864	        inputs: settled.map(sim.canonicalInput),
865	        settled: settled.length >= aliveAtStart,
866	        state: {
867	          teams: { blue: state.teamDamage.blue, red: state.teamDamage.red },
868	          tick: state.tick,
869	          units: Object.values(state.units).map((unit) => ({
870	            attacking: unit.attacking, health: unit.health, id: unit.id,
871	            position: unit.position, team: unit.team, velocity: unit.velocity,
872	          })),
873	        },
874	        state_hash: state.hash,
875	        tick: state.tick,
876	      };
877	      this.store.insertFrame(matchId, frame);
878	      rebuilt.push(frame);
879	      if (state.status !== 'running') {
880	        endedNaturally = true;
881	        break;
882	      }
883	    }
884	    if (state.tick === targetTick && !endedNaturally) {
885	      // A timeline that stops exactly at the requested frontier keeps the status
886	      // that frontier had, instead of inventing one from the tick count.
887	      state.status = resumeStatus;
888	    }
889	    // The frontier hash is always the hash of the state the frontier holds, so a
890	    // rolled-back match reports the same hash that its frame held before.
891	    state.hash = sim.stateHash(state);
892	    this.store.writeState(matchId, state, {});
893	    return { frames: rebuilt, state };
894	  }
895	
896	  /**
897	   * State snapshot *after* frame `tick`: the initial state for tick 0, otherwise
898	   * the snapshot frame `tick` itself stored. A missing frame is a hard failure
899	   * because every later frame depends on it.
900	   */
901	  snapshotAt(matchId, tick) {
902	    const config = this.config(matchId);
903	    if (tick <= 0) {
904	      return sim.initialState(config);
905	    }
906	    const frame = this.store.readFrames(matchId).find((candidate) => candidate.tick === tick);
907	    if (!frame) {
908	      throw new IntegrityError(`match ${matchId} has no recorded frame ${tick} to resume from`);
909	    }
910	    const state = sim.initialState(config);
911	    state.teamDamage = { blue: frame.state.teams.blue, red: frame.state.teams.red };
912	    state.tick = frame.state.tick;
913	    for (const unit of frame.state.units) {
914	      state.units[unit.id] = { ...unit };
915	    }
916	    return state;
917	  }
918	}
919	
920	module.exports = { Lockstep };
