      .prepare('INSERT INTO frames(match_id, tick, state_hash, delta_json, state_json, input_json, alive, settled) VALUES (?, ?, ?, ?, ?, ?, ?, ?)')
      .run(matchId, frame.tick, frame.state_hash, JSON.stringify(frame.delta), JSON.stringify(frame.state),
