class Cursor {
  constructor(bytes, offset, end) {
    this.bytes = bytes;
    this.offset = offset;
    this.end = end;
  }

  take(length, what) {
    if (this.offset + length > this.end) {
      throw new ErrReplayCorrupt(`replay is truncated: ${what} exceeds the data`);
    }
    const slice = this.bytes.subarray(this.offset, this.offset + length);
    this.offset += length;
    return slice;
  }

  u8(what) { return this.take(1, what).readUInt8(0); }
  u16(what) { return this.take(2, what).readUInt16BE(0); }
  u32(what) { return this.take(4, what).readUInt32BE(0); }
}
