serializeHeader() {
  const parts = [];
  const fixed = Buffer.alloc(4);
  fixed.writeUInt32BE(this.seed, 0) — wait seed u32, maxTicks u32, startFrame u32, frameCount u32 = 16 bytes + 32 hash + 2 + participants + 2 + extensions.
  const head = Buffer.alloc(16 + HASH_BYTES + 2);
